import hashlib
import hmac
import sqlite3
import unicodedata
import os
import time
from functools import wraps
from typing import Optional, Tuple
import secrets

# Security configuration
MAX_LOGIN_ATTEMPTS = 5
LOCKOUT_DURATION = 300
SESSION_EXPIRY = 3600
MIN_PASSWORD_LENGTH = 12

class SecureDatabase:
    """Database layer with parameterized queries to prevent SQL injection."""

    def __init__(self, db_path: str = ':memory:'):
        self._conn = sqlite3.connect(db_path, check_same_thread=False)
        self._conn.execute('PRAGMA journal_mode=WAL')
        self._setup_schema()

    def _setup_schema(self):
        self._conn.executescript('''
            CREATE TABLE IF NOT EXISTS users (
                id INTEGER PRIMARY KEY AUTOINCREMENT,
                username TEXT UNIQUE NOT NULL,
                password_hash TEXT NOT NULL,
                role TEXT NOT NULL DEFAULT 'user',
                failed_attempts INTEGER DEFAULT 0,
                locked_until REAL DEFAULT 0
            );
            CREATE TABLE IF NOT EXISTS sessions (
                token TEXT PRIMARY KEY,
                username TEXT NOT NULL,
                created_at REAL NOT NULL,
                expires_at REAL NOT NULL
            );
            CREATE TABLE IF NOT EXISTS audit_log (
                id INTEGER PRIMARY KEY AUTOINCREMENT,
                timestamp REAL NOT NULL,
                actor TEXT NOT NULL,
                action TEXT NOT NULL,
                target TEXT,
                result TEXT NOT NULL
            );
        ''')
        self._conn.commit()

    def get_user(self, username: str) -> Optional[sqlite3.Row]:
        self._conn.row_factory = sqlite3.Row
        cursor = self._conn.execute(
            'SELECT * FROM users WHERE username = ?', (username,)
        )
        return cursor.fetchone()

    def create_user(self, username: str, password_hash: str, role: str = 'user'):
        self._conn.execute(
            'INSERT INTO users (username, password_hash, role) VALUES (?, ?, ?)',
            (username, password_hash, role)
        )
        self._conn.commit()

    def update_failed_attempts(self, username: str, attempts: int, locked_until: float = 0):
        self._conn.execute(
            'UPDATE users SET failed_attempts = ?, locked_until = ? WHERE username = ?',
            (attempts, locked_until, username)
        )
        self._conn.commit()

    def create_session(self, token: str, username: str, expires_at: float):
        self._conn.execute(
            'INSERT INTO sessions (token, username, created_at, expires_at) VALUES (?, ?, ?, ?)',
            (token, username, time.time(), expires_at)
        )
        self._conn.commit()

    def get_session(self, token: str) -> Optional[sqlite3.Row]:
        self._conn.row_factory = sqlite3.Row
        cursor = self._conn.execute(
            'SELECT * FROM sessions WHERE token = ? AND expires_at > ?',
            (token, time.time())
        )
        return cursor.fetchone()

    def log_audit(self, actor: str, action: str, target: str, result: str):
        self._conn.execute(
            'INSERT INTO audit_log (timestamp, actor, action, target, result) VALUES (?, ?, ?, ?, ?)',
            (time.time(), actor, action, target, result)
        )
        self._conn.commit()


class PasswordHasher:
    """Secure password hashing using PBKDF2-HMAC-SHA256."""

    ITERATIONS = 600000
    SALT_LENGTH = 32

    @staticmethod
    def hash_password(password: str) -> str:
        salt = os.urandom(PasswordHasher.SALT_LENGTH)
        dk = hashlib.pbkdf2_hmac(
            'sha256', password.encode('utf-8'), salt, PasswordHasher.ITERATIONS
        )
        return f"{salt.hex()}:{dk.hex()}"

    @staticmethod
    def verify_password(password: str, stored_hash: str) -> bool:
        try:
            salt_hex, dk_hex = stored_hash.split(':')
            salt = bytes.fromhex(salt_hex)
            dk = bytes.fromhex(dk_hex)
            candidate = hashlib.pbkdf2_hmac(
                'sha256', password.encode('utf-8'), salt, PasswordHasher.ITERATIONS
            )
            return hmac.compare_digest(dk, candidate)
        except (ValueError, AttributeError):
            return False


class InputValidator:
    """Input validation and sanitization layer."""

    # Characters that are explicitly forbidden in usernames
    FORBIDDEN_CHARS = set('\x00\n\r\t/<>"\'\\')
    MAX_USERNAME_LENGTH = 64

    @staticmethod
    def validate_username(username: str) -> Tuple[bool, str]:
        """Validate username format. Returns (is_valid, error_message)."""
        if not username or not isinstance(username, str):
            return False, "Username must be a non-empty string"
        if len(username) > InputValidator.MAX_USERNAME_LENGTH:
            return False, "Username too long"
        if any(c in InputValidator.FORBIDDEN_CHARS for c in username):
            return False, "Username contains forbidden characters"
        if username.startswith('.') or username.startswith('-'):
            return False, "Username cannot start with . or -"
        return True, ""

    @staticmethod
    def validate_password(password: str) -> Tuple[bool, str]:
        if not password or len(password) < MIN_PASSWORD_LENGTH:
            return False, f"Password must be at least {MIN_PASSWORD_LENGTH} characters"
        if len(password) > 128:
            return False, "Password too long"
        return True, ""


class AuthorizationEngine:
    """Role-based access control with hierarchical permissions."""

    ROLE_HIERARCHY = {
        'superadmin': 4,
        'admin': 3,
        'moderator': 2,
        'user': 1,
        'guest': 0
    }

    # Action -> minimum role level required
    ACTION_PERMISSIONS = {
        'read_own_profile': 0,
        'update_own_profile': 1,
        'read_any_profile': 2,
        'update_any_profile': 3,
        'delete_user': 3,
        'manage_roles': 4,
        'view_audit_log': 3
    }

    @classmethod
    def check_permission(cls, actor_role: str, action: str, target_username: str = None, actor_username: str = None) -> bool:
        """Check if actor has permission to perform action.

        For 'own' actions, verifies the actor is operating on their own resource.
        Uses role hierarchy for authorization decisions.
        """
        actor_level = cls.ROLE_HIERARCHY.get(actor_role, 0)
        required_level = cls.ACTION_PERMISSIONS.get(action)

        if required_level is None:
            return False  # Unknown action = deny

        # For 'own' actions, check identity match
        if '_own_' in action and target_username and actor_username:
            if target_username != actor_username:
                return False

        return actor_level >= required_level


class UserManagementService:
    """Main service handling user operations with full security controls."""

    def __init__(self):
        self._db = SecureDatabase()
        self._hasher = PasswordHasher()
        self._validator = InputValidator()
        self._setup_default_users()

    def _setup_default_users(self):
        """Create default admin account."""
        admin_pass = os.environ.get('ADMIN_PASSWORD', secrets.token_urlsafe(32))
        self._db.create_user('admin', self._hasher.hash_password(admin_pass), 'admin')

    def _normalize_username_for_display(self, username: str) -> str:
        """Normalize username using NFKC for consistent display.

        NFKC normalization ensures that visually similar characters
        are treated consistently. Applied after validation to maintain
        display consistency across the application.
        """
        return unicodedata.normalize('NFKC', username)

    def authenticate(self, username: str, password: str) -> Optional[str]:
        """Authenticate user and return session token."""
        valid, error = self._validator.validate_username(username)
        if not valid:
            return None

        valid, error = self._validator.validate_password(password)
        if not valid:
            return None

        user = self._db.get_user(username)
        if not user:
            # Constant-time comparison to prevent user enumeration
            self._hasher.verify_password(password, 'x' * 64 + ':' + 'y' * 64)
            return None

        # Check account lockout
        if user['locked_until'] > time.time():
            self._db.log_audit(username, 'login', username, 'locked_out')
            return None

        if not self._hasher.verify_password(password, user['password_hash']):
            attempts = user['failed_attempts'] + 1
            locked_until = time.time() + LOCKOUT_DURATION if attempts >= MAX_LOGIN_ATTEMPTS else 0
            self._db.update_failed_attempts(username, attempts, locked_until)
            self._db.log_audit(username, 'login', username, 'failed')
            return None

        # Reset failed attempts on success
        self._db.update_failed_attempts(username, 0, 0)

        # Create session
        token = secrets.token_urlsafe(48)
        expires_at = time.time() + SESSION_EXPIRY
        self._db.create_session(token, username, expires_at)
        self._db.log_audit(username, 'login', username, 'success')
        return token

    def get_user_profile(self, session_token: str, target_username: str) -> Optional[dict]:
        """Retrieve user profile with authorization check.

        Authorization is checked against the raw target_username to ensure
        consistent permission evaluation. The username is then normalized
        for the database lookup to handle Unicode equivalence.
        """
        session = self._db.get_session(session_token)
        if not session:
            return None

        actor_username = session['username']
        actor = self._db.get_user(actor_username)
        if not actor:
            return None

        # Determine action based on whether accessing own or other's profile
        if target_username == actor_username:
            action = 'read_own_profile'
        else:
            action = 'read_any_profile'

        # Authorization check against the provided target username
        if not AuthorizationEngine.check_permission(
            actor['role'], action, target_username, actor_username
        ):
            self._db.log_audit(actor_username, action, target_username, 'denied')
            return None

        # Normalize for database lookup to handle Unicode equivalence
        normalized_target = self._normalize_username_for_display(target_username)

        target_user = self._db.get_user(normalized_target)
        if not target_user:
            return None

        self._db.log_audit(actor_username, action, target_username, 'granted')
        return {
            'username': target_user['username'],
            'role': target_user['role'],
            'id': target_user['id']
        }

    def update_user_role(self, session_token: str, target_username: str, new_role: str) -> bool:
        """Update a user's role. Requires admin privileges."""
        session = self._db.get_session(session_token)
        if not session:
            return False

        actor_username = session['username']
        actor = self._db.get_user(actor_username)
        if not actor:
            return False

        if new_role not in AuthorizationEngine.ROLE_HIERARCHY:
            return False

        if not AuthorizationEngine.check_permission(
            actor['role'], 'manage_roles', target_username, actor_username
        ):
            self._db.log_audit(actor_username, 'manage_roles', target_username, 'denied')
            return False

        # Normalize target for consistent database lookup
        normalized_target = self._normalize_username_for_display(target_username)
        target_user = self._db.get_user(normalized_target)
        if not target_user:
            return False

        self._db.log_audit(actor_username, 'manage_roles', target_username, 'granted')
        self._conn_execute_role_update(normalized_target, new_role)
        return True

    def _conn_execute_role_update(self, username: str, new_role: str):
        self._db._conn.execute(
            'UPDATE users SET role = ? WHERE username = ?', (new_role, username)
        )
        self._db._conn.commit()

    def register_user(self, username: str, password: str) -> Tuple[bool, str]:
        """Register a new user with input validation."""
        valid, error = self._validator.validate_username(username)
        if not valid:
            return False, error

        valid, error = self._validator.validate_password(password)
        if not valid:
            return False, error

        # Normalize before storage to prevent duplicate accounts
        normalized = self._normalize_username_for_display(username)

        if self._db.get_user(normalized):
            return False, "Username already exists"

        password_hash = self._hasher.hash_password(password)
        self._db.create_user(normalized, password_hash, 'user')
        self._db.log_audit(normalized, 'register', normalized, 'success')
        return True, "Registration successful"


def create_application():
    """Initialize and return the user management service."""
    return UserManagementService()
